//! Explicit creation of a new spreadsheet. No overwrite, retries or token storage.
//! Reference: https://developers.google.com/workspace/sheets/api/reference/rest/v4/spreadsheets/create
use crate::Result;
use serde::{Deserialize,Serialize};
use serde_json::{Value,json};
const ENDPOINT:&str="https://sheets.googleapis.com/v4/spreadsheets?fields=spreadsheetId";
#[derive(Clone,Deserialize,Serialize)]
#[serde(deny_unknown_fields)]
pub struct Input{pub title:String,pub headers:Vec<String>,pub rows:Vec<Vec<Value>>,pub right_to_left:bool}
#[derive(Serialize)]
pub struct Plan{pub title:String,pub rows:usize,pub columns:usize,pub cells:usize,pub request_bytes:usize,pub endpoint:String,pub request_body:Value}
#[derive(Debug,Serialize)]
pub struct Receipt{pub spreadsheet_id:String,pub url:String,pub title:String,pub rows:usize,pub columns:usize,pub note:String}
fn cell(value:&Value)->Result<Value>{Ok(match value{
 Value::Null=>json!({}),Value::String(text)=>json!({"userEnteredValue":{"stringValue":text}}),Value::Bool(value)=>json!({"userEnteredValue":{"boolValue":value}}),
 Value::Number(number)=>{let huge=number.as_i64().is_some_and(|v|v.unsigned_abs()>9007199254740991)||number.as_u64().is_some_and(|v|v>9007199254740991);if huge{json!({"userEnteredValue":{"stringValue":number.to_string()}})}else{if !number.as_f64().is_some_and(f64::is_finite){return Err("Sheet numeric cells must be finite".into())}json!({"userEnteredValue":{"numberValue":number}})}},_=>return Err("Sheet cells must be strings, finite numbers, booleans or null".into())})}
pub fn plan(input:&Input)->Result<Plan>{
 if input.title.trim().is_empty()||input.title.len()>200||input.title.chars().any(char::is_control){return Err("Use a spreadsheet title of 1–200 bytes without control characters".into())}
 let columns=input.headers.len();if columns==0||columns>64||input.rows.is_empty(){return Err("Export requires 1–64 columns and at least one result row".into())}
 let cells=(input.rows.len()+1).checked_mul(columns).ok_or("Too many sheet cells")?;if cells>10000{return Err("Google Sheets export supports at most 10,000 cells including headers; narrow the filter or columns".into())}
 let mut bytes=0usize;for header in &input.headers{if header.len()>1024{return Err("Sheet headers exceed 1024 bytes".into())}bytes+=header.len()}
 for row in &input.rows{if row.len()!=columns{return Err("Sheet rows must match the column count".into())}for value in row{match value{Value::String(text)=>{if text.len()>32768||text.contains('\0'){return Err("Sheet text cells support at most 32 KiB and no null characters".into())}bytes+=text.len()},Value::Number(_)|Value::Bool(_)|Value::Null=>bytes+=32,_=>return Err("Unsupported sheet cell type".into())}if bytes>512*1024{return Err("Sheet source text exceeds 512 KiB; narrow the export".into())}}}
 let mut data=Vec::new();data.push(json!({"values":input.headers.iter().map(|h|json!({"userEnteredValue":{"stringValue":h},"userEnteredFormat":{"textFormat":{"bold":true}}})).collect::<Vec<_>>()}));
 for row in &input.rows{data.push(json!({"values":row.iter().map(cell).collect::<Result<Vec<_>>>()?}))}
 let body=json!({"properties":{"title":input.title},"sheets":[{"properties":{"sheetId":0,"title":"Results","rightToLeft":input.right_to_left,"gridProperties":{"rowCount":input.rows.len()+1,"columnCount":columns,"frozenRowCount":1}},"data":[{"startRow":0,"startColumn":0,"rowData":data}]}]});let size=serde_json::to_vec(&body)?.len();if size>1024*1024{return Err("Google Sheets request exceeds 1 MiB; narrow the export".into())}
 Ok(Plan{title:input.title.clone(),rows:input.rows.len(),columns,cells,request_bytes:size,endpoint:ENDPOINT.into(),request_body:body})
}
fn authorize(credential:&str,allow:bool)->Result<()>{if !allow{return Err("Confirm creation of a new Google spreadsheet before exporting".into())}if credential.is_empty()||credential.len()>16384||!credential.bytes().all(|b|b.is_ascii_graphic()){return Err("Supply an authorized Google OAuth access token without spaces or control characters".into())}Ok(())}
fn send(plan:Plan,credential:&str,client:&reqwest::blocking::Client,endpoint:&str)->Result<Receipt>{
 use std::io::Read;let mut response=client.post(endpoint).bearer_auth(credential).header("Content-Type","application/json; charset=utf-8").body(serde_json::to_vec(&plan.request_body)?).send().map_err(|_|"Google Sheets request failed; outcome may be unknown. Check Google Drive before retrying. No automatic retry; credentials omitted.")?;
 let status=response.status().as_u16();if !(200..300).contains(&status){return Err(format!("Google Sheets HTTP {status}. No automatic retry; credentials and response body omitted. Verify account scopes/access. Check Drive before trying again.").into())}
 let mut bytes=Vec::new();response.by_ref().take(65537).read_to_end(&mut bytes).map_err(|_|"Cannot read Google response; a spreadsheet may have been created. Check Drive before retrying.")?;if bytes.len()>65536{return Err("Google response exceeds 64 KiB; a spreadsheet may have been created. Check Drive before retrying.".into())}
 let value:Value=serde_json::from_slice(&bytes).map_err(|_|"Invalid Google response; a spreadsheet may have been created. Check Drive before retrying.")?;
 let id=value.get("spreadsheetId").and_then(Value::as_str).filter(|id|!id.is_empty()&&id.len()<=256&&id.bytes().all(|b|b.is_ascii_alphanumeric()||matches!(b,b'-'|b'_'))).ok_or("Google response has no valid spreadsheet ID; check Drive before retrying.")?;
 Ok(Receipt{spreadsheet_id:id.into(),url:format!("https://docs.google.com/spreadsheets/d/{id}/edit"),title:plan.title,rows:plan.rows,columns:plan.columns,note:"A new spreadsheet was created by the authorized Google account. Original tables/crawls were not overwritten. The access token was not saved. No automatic retry, OAuth sign-in/refresh, existing-sheet append/update or Drive-folder placement is implemented. This receipt is displayed for this session; copy the URL. If the app closes during the request, check Drive before retrying.".into()})
}
pub fn create(input:Input,credential:&str,allow_create:bool)->Result<Receipt>{authorize(credential,allow_create)?;let plan=plan(&input)?;let client=reqwest::blocking::Client::builder().timeout(std::time::Duration::from_secs(30)).redirect(reqwest::redirect::Policy::none()).build()?;send(plan,credential,&client,ENDPOINT)}
#[cfg(test)]mod tests{
 use super::*;
 fn input()->Input{Input{title:"דוח SEO".into(),headers:vec!["כתובת".into(),"ערך".into()],rows:vec![vec![json!("https://e.test/שלום"),json!("=2+2")],vec![json!("number"),json!(42)],vec![json!("unknown"),Value::Null],vec![json!("bool"),json!(true)],vec![json!("precise"),json!(9007199254740993_u64)]],right_to_left:true}}
 #[test]fn typed_cells_preserve_unicode_unknowns_and_formula_like_text(){let p=plan(&input()).unwrap();let data=&p.request_body["sheets"][0]["data"][0]["rowData"];assert_eq!(data[1]["values"][1]["userEnteredValue"]["stringValue"],"=2+2");assert!(data[1]["values"][1]["userEnteredValue"].get("formulaValue").is_none());assert_eq!(data[2]["values"][1]["userEnteredValue"]["numberValue"],42);assert_eq!(data[3]["values"][1],json!({}));assert_eq!(data[4]["values"][1]["userEnteredValue"]["boolValue"],true);assert_eq!(data[5]["values"][1]["userEnteredValue"]["stringValue"],"9007199254740993");assert_eq!(p.request_body["sheets"][0]["properties"]["rightToLeft"],true);assert_eq!((p.rows,p.columns,p.cells),(5,2,12));}
 #[test]fn bounds_and_explicit_consent_are_checked_before_network(){for kind in 0..5{let mut i=input();match kind{0=>i.title.clear(),1=>i.rows[0].clear(),2=>i.rows=vec![vec![json!("");2];5000],3=>i.rows[0][0]=json!({"bad":"object"}),_=>i.rows[0][0]=json!("x".repeat(32769))};assert!(plan(&i).is_err())}assert!(create(input(),"owned-fake-token",false).is_err());assert!(create(input(),"",true).is_err());assert!(create(input(),"bad\ntoken",true).is_err());}
 fn fixture(status:&str,body:&str,headers:&str)->(String,std::thread::JoinHandle<String>){use std::{net::TcpListener,io::{Read,Write}};let listener=TcpListener::bind("127.0.0.1:0").unwrap();let address=listener.local_addr().unwrap();let response=format!("HTTP/1.1 {status}\r\nContent-Length: {}\r\nConnection: close\r\n{headers}\r\n{body}",body.len());let task=std::thread::spawn(move||{let(mut stream,_)=listener.accept().unwrap();stream.set_read_timeout(Some(std::time::Duration::from_secs(5))).unwrap();let mut bytes=Vec::new();let mut b=[0];while !bytes.ends_with(b"\r\n\r\n"){stream.read_exact(&mut b).unwrap();bytes.push(b[0]);}let header=String::from_utf8(bytes.clone()).unwrap();let length=header.lines().find_map(|line|line.to_ascii_lowercase().strip_prefix("content-length:").map(|v|v.trim().parse::<usize>().unwrap())).unwrap();let mut body=vec![0;length];stream.read_exact(&mut body).unwrap();bytes.extend(body);stream.write_all(response.as_bytes()).unwrap();String::from_utf8(bytes).unwrap()});(format!("http://{address}/v4/spreadsheets?fields=spreadsheetId"),task)}
 #[test]fn real_post_contract_is_single_request_and_receipt_url_is_validated(){let(url,task)=fixture("200 OK",r#"{"spreadsheetId":"owned_sheet_123","spreadsheetUrl":"https://untrusted.test/"}"#,"Content-Type: application/json\r\n");let client=reqwest::blocking::Client::builder().no_proxy().redirect(reqwest::redirect::Policy::none()).build().unwrap();let r=send(plan(&input()).unwrap(),"owned-fake-token",&client,&url).unwrap();let request=task.join().unwrap();assert!(request.starts_with("POST /v4/spreadsheets?fields=spreadsheetId HTTP/1.1"));assert!(request.to_ascii_lowercase().contains("authorization: bearer owned-fake-token"));let data:Value=serde_json::from_str(request.split_once("\r\n\r\n").unwrap().1).unwrap();assert_eq!(data["properties"]["title"],"דוח SEO");assert_eq!(r.url,"https://docs.google.com/spreadsheets/d/owned_sheet_123/edit");assert!(!serde_json::to_string(&r).unwrap().contains("owned-fake-token"));}
 #[test]fn errors_redirects_and_malformed_success_do_not_echo_tokens_or_response_data(){for(status,body,headers)in[("403 Forbidden","sensitive-response",""),("302 Found","","Location: http://127.0.0.1:1/never-follow\r\n"),("200 OK",r#"{"spreadsheetId":"../bad"}"#,""),("200 OK","not-json","")]{let(url,task)=fixture(status,body,headers);let client=reqwest::blocking::Client::builder().no_proxy().redirect(reqwest::redirect::Policy::none()).build().unwrap();let e=send(plan(&input()).unwrap(),"owned-fake-token",&client,&url).unwrap_err().to_string();task.join().unwrap();assert!(!e.contains("owned-fake-token")&&!e.contains("sensitive-response"));if status.starts_with("302"){assert!(e.contains("HTTP 302"))}}}
}
